function query(){const p=new URLSearchParams();for(const [k,v] of new FormData($('filters'))){if(!v)continue;if(k.endsWith('_from')||k.endsWith('_to')){const d=new Date(v+'T00:00:00');if(k.endsWith('_to'))d.setDate(d.getDate()+1);p.set(k,String(Math.floor(d.getTime()/1000)))}else p.set(k,v.trim())}p.set('offset',String(userOffset));return p.toString()}
function detail(u){const card=el('div',undefined,'detail');card.append(el('h3',fullName(u)),el('p','ID специалиста: '+u.id+(u.admin_id?' · ID администратора: '+u.admin_id:'')),el('p',u.email+' · '+genderLabel(u.gender)),el('p','Регистрация: '+date(u.created)+' · Последняя активность: '+date(u.last_seen)));card.append(el('p','Дата рождения: '+(u.birth_date?u.birth_date.split('-').reverse().join('.'):'—')+' · Возраст: '+age(u.birth_date,u.timezone||'UTC')),el('p','Страна: '+(u.country||'—')+' · Город: '+(u.city||'—')));const legal=el('div',undefined,'legal-admin');legal.append(el('h3','Юридические документы'),el('p',u.legal_acceptance?'Лицензионное соглашение · редакция '+u.legal_acceptance.version+' · '+(u.legal_acceptance.language||'—')+' · принято '+date(u.legal_acceptance.accepted_at):'Принятие соглашения не зафиксировано'),el('p',u.legal_acceptance?'С информацией об обработке персональных данных ознакомлен':'Ознакомление не зафиксировано'));card.append(legal);if(u.timezone){const clock=el('strong',formatClock(u.timezone));clock.dataset.clockZone=u.timezone;const line=el('p','Местное время ('+u.timezone+'): ');line.append(clock);card.append(line);}if(u.role==='admin'||u.deleted){card.append(el('p',u.deleted?'Аккаунт архивирован':'Администратор — ограничения не применяются'));return card}
card.append(el('p','Клиентов: '+(u.metrics?.clients??'Нет данных')+' · Входов: '+(u.metrics?.logins??0)+' · Активных дней за 30 дней: '+(u.metrics?.days30??0)+' · Данные базы: '+date(u.metrics?.reported_at)));card.append(el('p','AI сегодня: '+(u.ai_usage?.total??0)+' · чат '+(u.ai_usage?.areas?.chat??0)+' · сессии '+(u.ai_usage?.areas?.session??0)+' · гипотезы '+(u.ai_usage?.areas?.hypothesis??0)+' · диагностика '+(u.ai_usage?.areas?.diagnosis??0)));const grid=el('div',undefined,'limits'),inputs={};for(const [key,value] of Object.entries(u.limits)){const l=el('label',labels[key]),i=el('input');if(key==='clients'||key==='sessions'||key==='ai_daily'||['ai_chat','ai_session','ai_hypothesis','ai_diagnosis'].includes(key)){i.type='number';i.min='0';i.max='1000000';i.placeholder='Без лимита';i.value=value??'';}else{i.type='checkbox';i.checked=value;}l.append(i);grid.append(l);inputs[key]=i;}const l=el('label','Аккаунт активен'),enabled=el('input');enabled.type='checkbox';enabled.checked=u.enabled;l.append(enabled);grid.append(l);
const save=el('button','Сохранить ограничения'),del=el('button','Удалить специалиста','danger');save.onclick=async()=>{save.disabled=true;try{const limits={};for(const [k,i] of Object.entries(inputs))limits[k]=i.type==='checkbox'?i.checked:i.value===''?null:Number(i.value);await api('admin/update',{id:u.id,limits,enabled:enabled.checked});$('userDialog').close();await loadAdmin();msg('Настройки сохранены.')}catch(e){msg(e.message)}finally{save.disabled=false}};
del.onclick=async()=>{if(!await confirmAction('Архивировать специалиста '+u.id+' и завершить все его сеансы? ID останется зарезервированным.','Архивация специалиста','Архивировать'))return;try{await api('admin/delete',{id:u.id});$('userDialog').close();await loadAdmin();msg('Специалист архивирован.')}catch(e){msg(e.message)}};const actions=el('div',undefined,'actions');actions.append(save,del);card.append(grid,actions);return card}
async function loadUsers(){const result=await api('admin/users?'+query());$('totalUsers').textContent=result.total;$('userCount').textContent='Найдено: '+result.total+' · Страница '+(Math.floor(userOffset/50)+1);$('prevUsers').disabled=userOffset===0;$('nextUsers').disabled=userOffset+50>=result.total;const wrap=el('div',undefined,'tablewrap'),table=el('table'),head=el('tr');for(const title of ['ID','Имя и фамилия','Email','Пол','Регистрация','Активность','Статус'])head.append(el('th',title));const thead=el('thead');thead.append(head);table.append(thead);const tbody=el('tbody');for(const u of result.items){const row=el('tr'),id=el('button',u.id,'idbutton'),td=el('td');id.type='button';id.setAttribute('aria-expanded','false');td.append(id);if(u.admin_id)td.append(el('div','Админ: '+u.admin_id));row.append(td);for(const value of [fullName(u),u.email,genderLabel(u.gender),date(u.created),date(u.last_seen),u.deleted?'Удалён':u.role==='admin'?'Администратор':u.enabled?'Активен':'Заблокирован'])row.append(el('td',value));id.removeAttribute('aria-expanded');id.setAttribute('aria-haspopup','dialog');id.onclick=()=>{$('dialogBody').replaceChildren(detail(u));$('userDialog').showModal()};tbody.append(row)}if(!result.items.length){const tr=el('tr'),td=el('td','Специалисты не найдены','empty');td.colSpan=7;tr.append(td);tbody.append(tr)}table.append(tbody);wrap.append(table);$('users').replaceChildren(wrap)}
const actionsText={'login':'Вход','registered':'Регистрация специалиста','invite':'Создание приглашения','invite-revoke':'Отзыв приглашения','update-access':'Изменение прав','delete':'Удаление (архивирование)','profile':'Изменение профиля','logout':'Выход'};
function person(u){return [u.admin_id?'Админ #'+u.admin_id:u.id?'#'+u.id:'',u.first_name,u.last_name,u.email].filter(Boolean).join(' ')}
async function loadAudit(){const result=await api('admin/audit?offset='+auditOffset);$('auditCount').textContent='Записей: '+result.total+' · Страница '+(Math.floor(auditOffset/100)+1);$('prevAudit').disabled=auditOffset===0;$('nextAudit').disabled=auditOffset+100>=result.total;const wrap=el('div',undefined,'tablewrap'),table=el('table'),head=el('tr'),thead=el('thead'),body=el('tbody');for(const t of ['№','Дата и время','Действие','Исполнитель','Получатель','Изменения'])head.append(el('th',t));thead.append(head);table.append(thead);for(const r of result.items){const row=el('tr');for(const v of ['#'+r.id,date(r.created),actionsText[r.action]||r.action,person(r.actor),person(r.target)])row.append(el('td',v));const td=el('td');for(const [key,v] of Object.entries(r.details.changes||{}))td.append(el('div',(labels[key]||({enabled:'Аккаунт активен',deleted:'Удалён',first_name:'Имя',last_name:'Фамилия',gender:'Пол',invitation:'Приглашение',expiry:'Срок (часы)',birth_date:'Дата рождения',country:'Страна',city:'Город',timezone:'Часовой пояс'}[key])||key)+': '+val(v.from)+' → '+val(v.to)));if(!td.childNodes.length)td.textContent='—';row.append(td);body.append(row)}if(!result.items.length){const row=el('tr'),td=el('td','Пока нет записей','empty');td.colSpan=6;row.append(td);body.append(row)}table.append(body);wrap.append(table);$('audit').replaceChildren(wrap)}
