onboard.elements.birth_date.addEventListener('input',e=>{
 if(e.inputType?.startsWith('delete'))return;
 const input=e.target,digits=input.value.replace(/\D/g,'').slice(0,8);
 const formatted=[digits.slice(0,2),digits.slice(2,4),digits.slice(4)].filter(Boolean).join('.');
 if(input.value!==formatted)input.value=formatted;
});
function onboardingError(field,message){
 const label=field.closest('label');let error=label.querySelector('.field-error');
 if(!error){error=el('span',undefined,'field-error');error.id='onboard-error-'+field.name;error.setAttribute('aria-live','polite');label.append(error);}
 error.textContent=message;error.hidden=!message;
 field.classList.toggle('field-invalid',Boolean(message));
 if(message){field.setAttribute('aria-invalid','true');field.setAttribute('aria-describedby',error.id);}
 else{field.removeAttribute('aria-invalid');field.removeAttribute('aria-describedby');}
 return !message;
}
function validateOnboardField(field){
 const value=field.value.trim();let error='';
 if(field.name==='first_name'||field.name==='last_name'){
  if(!value)error=field.name==='first_name'?'Введите имя.':'Введите фамилию.';
 }else if(field.name==='birth_date'){
  const iso=isoBirth(value);
  if(!value)error='Укажите дату рождения.';
  else if(!iso)error='Введите существующую дату в формате ДД.ММ.ГГГГ, например 15.08.1990.';
  else if(iso<'1900-01-01'||iso>localDate(browserZone))error='Проверьте год рождения: дата не может быть в будущем или раньше 1900 года.';
  else if(Number(age(iso,browserZone))<18)error='Регистрация доступна с 18 лет.';
 }
 return onboardingError(field,error);
}
const onboardFields=['first_name','last_name','birth_date'].map(k=>onboard.elements[k]);
for(const field of onboardFields){
 field.addEventListener('blur',()=>{if(field.value.trim()||field.classList.contains('field-invalid'))validateOnboardField(field)});
 field.addEventListener('input',()=>{if(field.classList.contains('field-invalid')||field.name==='birth_date'&&field.value.length===10)validateOnboardField(field)});
}
onboard.noValidate=true;
function focusOnboardError(field){field.focus({preventScroll:true});field.scrollIntoView({block:'center',behavior:'auto'});}
onboard.onsubmit=async e=>{
 e.preventDefault();if(legalBusy)return;
 $('onboardingError').hidden=true;
 const invalid=onboardFields.filter(field=>!validateOnboardField(field));
 if(invalid.length){focusOnboardError(invalid[0]);return;}
 if(!licenseCheck.checked||!privacyCheck.checked){$('onboardingError').textContent='Ознакомьтесь с документами и установите обе отметки.';$('onboardingError').hidden=false;return;}
 legalBusy=true;updateFinish();
 try{
  const data=Object.fromEntries(new FormData(onboard));data.birth_date=isoBirth(data.birth_date);
  data.language=accountLocale;data.legal_version='1.0';data.license_accepted=licenseCheck.checked;data.privacy_read=privacyCheck.checked;
  await api('onboarding',data);location.replace('/');
 }catch(e){
  const message=e.message||'Не удалось завершить регистрацию.';
  if(/дат[ауые]|рождени|18 лет/i.test(message)){onboardingError(onboard.elements.birth_date,message);focusOnboardError(onboard.elements.birth_date);}
  else if(/имя и фамилию/i.test(message)){onboardingError(onboard.elements.first_name,message);focusOnboardError(onboard.elements.first_name);}
  else{$('onboardingError').textContent=message;$('onboardingError').hidden=false;$('onboardingError').scrollIntoView({block:'center'});}
  legalBusy=false;updateFinish();
 }
};
$('onboardingLogout').onclick=async()=>{try{await api('logout',{});location.reload()}catch(e){msg(e.message)}};
$('logout').onclick=async()=>{try{await api('logout',{});location.reload()}catch(e){msg(e.message)}};

let inviteOffset=0;

function confirmAction(message,title='Подтверждение действия',positive='Подтвердить'){
 return new Promise(resolve=>{
  const d=$('actionConfirm'),form=$('actionConfirmForm');
  if(d.open){resolve(false);return}
  $('actionConfirmTitle').textContent=title;$('actionConfirmText').textContent=message;$('actionConfirmYes').textContent=positive;
  d.returnValue='cancel';d.addEventListener('close',()=>resolve(d.returnValue==='yes'),{once:true});d.showModal();form.querySelector('[value=cancel]').focus();
 });
}
function shortPerson(u){return u?[u.first_name,u.last_name].filter(Boolean).join(' ')||'Не указано':'—'}
function statusBadge(status){return el('span',inviteStates[status]||status,'invite-status '+status)}
async function copyCode(code,button){try{await navigator.clipboard.writeText(code.value);button.textContent='Скопировано'}catch{code.focus();code.select();button.textContent='Скопируйте выделенный код'}}
let detailRequest=0;
async function openInvite(row,number){
 const d=$('inviteDetailDialog'),body=$('inviteDetailBody'),request=++detailRequest;body.replaceChildren(el('p','Загрузка…'));if(!d.open)d.showModal();
 try{
  const item=await api('admin/invite-detail?id='+encodeURIComponent(row.id));if(!d.open||request!==detailRequest)return;
  body.replaceChildren();
  const top=el('div',undefined,'invite-detail-top');top.append(el('h3','Лицензия № '+number),statusBadge(item.status));body.append(top);
  const keybox=el('div',undefined,'invite-keybox');keybox.append(el('strong','Лицензионный код'));
  if(item.code){const code=el('textarea');code.readOnly=true;code.rows=2;code.value=item.code;code.className='invite-full-code';code.setAttribute('aria-label','Полный код приглашения');const copy=el('button','Копировать код');copy.type='button';copy.onclick=()=>copyCode(code,copy);keybox.append(code,copy)}
  else keybox.append(el('p',item.status==='active'?'Старый код невозможно восстановить из хеша. Перевыпустите приглашение.':'Исходный код недоступен. Номер лицензии сохранён.','muted'));
  body.append(keybox);
  const label=el('label','Для кого создано / комментарий'),comment=el('textarea');comment.maxLength=250;comment.rows=2;comment.value=item.comment||'';comment.placeholder='Имя специалиста или примечание';label.append(comment);body.append(label);
  const save=el('button','Сохранить комментарий','secondary');save.type='button';save.onclick=async()=>{save.disabled=true;try{await api('admin/invite-comment',{id:row.id,comment:comment.value});await loadInvites();save.textContent='Сохранено'}catch(e){save.textContent=e.message}finally{save.disabled=false}};body.append(save);
  const info=el('div',undefined,'invite-detail-info');
  for(const [k,v] of [['Создал',shortPerson(item.created_by)],['Email',item.email||'Без привязки'],['Создано',date(item.created)],['Активация до',item.expires?date(item.expires):'Бессрочно'],...(item.used_by?[['Активировал',shortPerson(item.used_by)],['Дата активации',date(item.used_at)]]:[])]){
   const line=el('div',undefined,'invite-meta');line.append(el('small',k),el('strong',v));info.append(line);
  }
  body.append(info);
  const permanent=el('div',undefined,'invite-meta');permanent.append(el('small','Уникальный номер лицензии'),el('strong',item.license_number||item.id));body.append(permanent);
  if(item.specialist){
   const u=item.specialist, section=el('div',undefined,'license-owner');section.append(el('h3','Специалист · бессрочная лицензия'));
   const details=el('div',undefined,'invite-detail-info');
   for(const [k,v] of [['ID специалиста',u.id],['Имя и фамилия',shortPerson(u)],['Email',u.email],['Дата рождения',u.birth_date||'—'],['Пол',genderLabel(u.gender)],['Страна',u.country||'—'],['Город',u.city||'—'],['Часовой пояс',u.timezone||'—'],['Аккаунт',u.deleted?'Архивирован':u.enabled?'Активен':'Заблокирован'],['Клиентов',u.metrics?.clients??'Нет данных'],['Последняя активность',date(u.last_seen)],['Входов',u.metrics?.logins??0],['Активных дней за 30 дней',u.metrics?.days30??0],['AI сегодня',u.ai_usage?.total??0]]){
    const line=el('div',undefined,'invite-meta');line.append(el('small',k),el('strong',String(v??'—')));details.append(line);
   }
   section.append(details);
   const manage=el('button','Настройки специалиста','secondary');manage.type='button';manage.onclick=()=>{d.close();$('dialogBody').replaceChildren(detail(u));$('userDialog').showModal()};section.append(manage);body.append(section);
  }
  const actions=el('div',undefined,'invite-actions');addInviteActions(actions,item,()=>d.close(),true);body.append(actions);
 }catch(e){if(request===detailRequest)body.replaceChildren(el('p',e.message))}
}
$('closeInviteDetail').onclick=()=>$('inviteDetailDialog').close();
$('inviteDetailDialog').addEventListener('close',()=>{detailRequest++;$('inviteDetailBody').replaceChildren()});
const inviteForm=$('invite'),inviteFilters=$('inviteFilters');
const inviteStates={active:'Действует',used:'Активирован',expired:'Истёк',revoked:'Отозван'};
function setInviteMode(){const required=inviteForm.elements.mode.value==='email';$('inviteEmailRow').hidden=!required;inviteForm.elements.email.required=required;inviteForm.elements.email.disabled=!required}
inviteForm.elements.mode.onchange=setInviteMode;setInviteMode();
function showInviteCode(r){$('newInviteResult').hidden=false;$('inviteCode').textContent=r.invite;$('inviteCode').dataset.code=r.invite;$('copyInvite').hidden=false}
function inviteQuery(){const q=new URLSearchParams(new FormData(inviteFilters));q.set('offset',String(inviteOffset));return q.toString()}

function addInviteActions(group,row,after=()=>{},inside=false){
 function action(label,cls,endpoint,message,extra={},success='Готово'){
  const b=el('button',label,cls);b.type='button';group.append(b);
  b.onclick=async()=>{if(!await confirmAction(message,label,label))return;for(const btn of group.querySelectorAll('button'))btn.disabled=true;
   try{const result=await api(endpoint,{id:row.id,...extra});after();if(result.invite){showInviteCode(result);inviteOffset=0;}await loadInvites();msg(success)}
   catch(e){msg(e.message)}finally{for(const btn of group.querySelectorAll('button'))btn.disabled=false}
  };
 }
 if(row.status==='active'){
  action('Отозвать','secondary','admin/invite-revoke','Код перестанет действовать. Запись лицензии будет сохранена.',{},'Приглашение отозвано.');
  action('Перевыпустить','secondary','admin/invite-reissue','Создать новый код? Старый перестанет действовать.',{hours:Number(inviteForm.elements.hours.value)},'Новый код создан.');
 }else if(inside&&['revoked','expired'].includes(row.status))action('Удалить','danger','admin/invite-delete','Удалить неактивированную лицензию из реестра? Номер останется зарезервированным.',{},'Приглашение удалено.');
}
let inviteRequest=0;
async function loadInvites(){const seq=++inviteRequest;$('inviteList').replaceChildren(el('p','Загрузка приглашений…','muted'));let result;try{result=await api('admin/invites?'+inviteQuery());}catch(e){if(seq===inviteRequest)$('inviteList').replaceChildren(el('p',e.message,'muted'));throw e;}if(seq!==inviteRequest)return;if(!result.items.length&&inviteOffset>0){inviteOffset=Math.max(0,inviteOffset-50);return loadInvites()}$('inviteCount').textContent='Найдено: '+result.total+' · Страница '+(Math.floor(inviteOffset/50)+1);$('prevInvites').disabled=inviteOffset===0;$('nextInvites').disabled=inviteOffset+50>=result.total;
 const wrap=el('div',undefined,'tablewrap'),table=el('table'),thead=el('thead'),head=el('tr'),body=el('tbody');
 for(const t of ['№','Лицензия / для кого','Создано','Активация до','Статус','Активировал','Действия'])head.append(el('th',t));thead.append(head);table.append(thead);
 for(const [index,row] of result.items.entries()){const number=inviteOffset+index+1,tr=el('tr'),code=el('td'),open=el('button',row.preview,'invite-open');open.type='button';open.onclick=()=>openInvite(row,number);code.append(open,el('small',row.comment||row.email||'Не указано'));tr.append(el('td',String(number)),code,el('td',date(row.created)),el('td',row.status==='used'?'Бессрочно':row.expires?date(row.expires):'Бессрочно'));
 const status=el('td');status.append(statusBadge(row.status));tr.append(status);
 const used=el('td');used.textContent=shortPerson(row.used_by);tr.append(used);
 const actions=el('td'),group=el('div',undefined,'invite-actions'),detail=el('button','Открыть','secondary');detail.type='button';detail.onclick=()=>openInvite(row,number);group.append(detail);addInviteActions(group,row);actions.append(group);tr.append(actions);body.append(tr)}
 if(!result.items.length){const tr=el('tr'),td=el('td','Приглашений пока нет','empty');td.colSpan=7;tr.append(td);body.append(tr)}table.append(body);wrap.append(table);$('inviteList').replaceChildren(wrap);
}
$('refreshInvites').onclick=()=>go(loadInvites);
inviteFilters.onsubmit=e=>{e.preventDefault();inviteOffset=0;go(loadInvites)};
inviteFilters.elements.status.addEventListener('change',()=>{inviteOffset=0;go(loadInvites)});
$('prevInvites').onclick=()=>{inviteOffset=Math.max(0,inviteOffset-50);go(loadInvites)};
$('nextInvites').onclick=()=>{inviteOffset+=50;go(loadInvites)};
inviteForm.onsubmit=async e=>{e.preventDefault();const submit=inviteForm.querySelector('button');submit.disabled=true;try{const fields=inviteForm.elements;const result=await api('admin/invite',{email:fields.mode.value==='email'?fields.email.value.trim().toLowerCase():'',hours:Number(fields.hours.value),comment:fields.comment.value.trim()});showInviteCode(result);msg('Приглашение создано. Скопируйте код.');inviteOffset=0;inviteFilters.reset();await loadInvites()}catch(e){msg(e.message)}finally{submit.disabled=false}};

